import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.KXf_4Ogb.js";const u=JSON.parse('{"title":"Repository Guidelines","description":"","frontmatter":{},"headers":[],"relativePath":"AGENTS.md","filePath":"AGENTS.md","lastUpdated":null}'),o={name:"AGENTS.md"};function n(d,e,l,r,c,p){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="repository-guidelines" tabindex="-1">Repository Guidelines <a class="header-anchor" href="#repository-guidelines" aria-label="Permalink to &quot;Repository Guidelines&quot;">​</a></h1><h2 id="project-structure-module-organization" tabindex="-1">Project Structure &amp; Module Organization <a class="header-anchor" href="#project-structure-module-organization" aria-label="Permalink to &quot;Project Structure &amp; Module Organization&quot;">​</a></h2><p>This repository is a VitePress site for a Chinese technical blog. Root-level Markdown files (<code>index.md</code>, <code>api-examples.md</code>, and <code>markdown-examples.md</code>) provide the home page and examples. Long-form articles belong in <code>notes/</code> (for example, <code>notes/RoboMasterReview.md</code>). Site configuration lives in <code>.vitepress/config.mts</code>; theme overrides are in <code>.vitepress/theme/</code> (TypeScript and CSS). Store referenced images in <code>images/</code> and videos in <code>video/</code>, using paths that work with the configured <code>/my-blog/</code> base URL. Generated output under <code>.vitepress/dist/</code> should not be edited manually.</p><h2 id="build-test-and-development-commands" tabindex="-1">Build, Test, and Development Commands <a class="header-anchor" href="#build-test-and-development-commands" aria-label="Permalink to &quot;Build, Test, and Development Commands&quot;">​</a></h2><p>Install the locked dependency set before working:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span></code></pre></div><p>Run the local authoring server with hot reload:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><p>Build the production site (the same build used by CI):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>Preview an already-built site locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span></span></code></pre></div><p>The <code>npm test</code> script is currently a placeholder and exits with an error; validate documentation changes with a successful production build instead.</p><h2 id="coding-style-naming-conventions" tabindex="-1">Coding Style &amp; Naming Conventions <a class="header-anchor" href="#coding-style-naming-conventions" aria-label="Permalink to &quot;Coding Style &amp; Naming Conventions&quot;">​</a></h2><p>Use Markdown with clear Chinese headings, short paragraphs, and fenced code blocks tagged with the language. Keep front matter at the top of each page. Follow the existing two-space style in <code>.vitepress/config.mts</code>, use single quotes in TypeScript, and keep configuration comments concise. Name article files and media with descriptive PascalCase or snake-free names (for example, <code>RoboMasterReview.md</code>, <code>competition_video1.mp4</code>).</p><h2 id="testing-guidelines" tabindex="-1">Testing Guidelines <a class="header-anchor" href="#testing-guidelines" aria-label="Permalink to &quot;Testing Guidelines&quot;">​</a></h2><p>There is no automated unit-test suite or coverage requirement. Before submitting content or theme changes, run <code>npm run docs:build</code> and inspect affected pages with <code>npm run docs:preview</code>; verify internal links, math formulas, image/video loading, and the browser console for errors.</p><h2 id="commit-pull-request-guidelines" tabindex="-1">Commit &amp; Pull Request Guidelines <a class="header-anchor" href="#commit-pull-request-guidelines" aria-label="Permalink to &quot;Commit &amp; Pull Request Guidelines&quot;">​</a></h2><p>History uses both Chinese summaries and Conventional Commit-style prefixes (<code>feat:</code>, <code>fix:</code>). Write an imperative, focused subject (optionally prefixed with <code>feat:</code>, <code>fix:</code>, or <code>docs:</code>), and keep unrelated edits out of the commit. Pull requests should explain the user-visible change, list validation commands, link relevant issues, and include screenshots or a preview URL for layout/theme changes. Ensure the Pages build passes before requesting review.</p><h2 id="deployment-configuration-notes" tabindex="-1">Deployment &amp; Configuration Notes <a class="header-anchor" href="#deployment-configuration-notes" aria-label="Permalink to &quot;Deployment &amp; Configuration Notes&quot;">​</a></h2><p>Pushes to <code>main</code> trigger <code>.github/workflows/deploy.yml</code>, which runs <code>npm ci</code>, builds VitePress with Node 20, and deploys <code>.vitepress/dist</code> to GitHub Pages. Preserve the <code>base: &#39;/my-blog/&#39;</code> setting and avoid committing secrets or local cache artifacts.</p>',21)])])}const m=i(o,[["render",n]]);export{u as __pageData,m as default};
